#!/bin/bash
# voiced: install the LaunchDaemons. Review, then run with sudo.
# Generated by `voiced install`; safe to re-run after a config change.
set -euo pipefail
user=someone
home=/Users/someone
voiced=/Users/someone/.voiced/bin/voiced
labels=(org.example.voiced.stt org.example.voiced.tts org.example.voiced.watchdog)

fail() { echo "refused: $*" >&2; exit 1; }
[ "$(id -u)" -eq 0 ] || fail "run this with sudo"
uid="$(id -u -- "$user" 2>/dev/null)" || fail "no such user $user"
# Regular accounts only: not root or system accounts (below 500), not nobody (4294967294).
[[ "$uid" =~ ^[0-9]+$ ]] && (( uid >= 500 && uid < 2147483648 )) \
    || fail "$user is not a regular account (uid $uid)"
[ -d "$home" ] && [ "$(stat -L -f %u -- "$home")" = "$uid" ] || fail "$home is not owned by $user"

# One install or uninstall at a time, the app's included: the same kernel lock (flock on
# fd 9, through perl, held until this shell exits).
lockfile=/var/run/voiced-privileged.lock
exec 9>>"$lockfile" || fail "cannot open $lockfile"
rc=0
perl -MFcntl=:flock -e 'open(my $fh, ">&=9") or exit 2; flock($fh, LOCK_EX | LOCK_NB) and exit 0;
    exit($!{EWOULDBLOCK} ? 1 : 2)' || rc=$?
case "$rc" in
0) ;;
1) fail "another voiced install or uninstall is running" ;;
*) fail "cannot lock $lockfile (exit $rc)" ;;
esac

# One install per Mac: never replace another account's daemons (compared by uid). An install
# whose account no longer exists is orphaned and may be replaced.
for label in "${labels[@]}"; do
    existing="/Library/LaunchDaemons/$label.plist"
    [ -e "$existing" ] || continue
    owner="$(plutil -extract UserName raw -o - -- "$existing" 2>/dev/null || true)"
    if [ -n "$owner" ] && ! owner_uid="$(id -u -- "$owner" 2>/dev/null)"; then
        echo "$label: orphaned install of deleted account $owner, taking it over"
        continue
    fi
    [ -n "$owner" ] && [ "$owner_uid" = "$uid" ] \
        || fail "voiced is already installed for ${owner:-another account} on this Mac"
done

# With the application firewall on, allow the services' Python, which nobody can approve
# before login: resolved as the user, and only a regular file of theirs inside their home.
# A Python outside the home (a Homebrew keg's, shared with other programs) is left alone.
firewall() {
    local fw=/usr/libexec/ApplicationFirewall/socketfilterfw entry python realhome
    [ -x "$fw" ] && "$fw" --getglobalstate | grep -q enabled || return 0
    realhome="$(sudo -n -u "$user" -- realpath -- "$home")" \
        && entry="$(sudo -n -u "$user" -- realpath -- "$voiced")" \
        && python="$(sudo -n -u "$user" -- realpath -- "${entry%/voiced}/python")" \
        || { echo "warning: the firewall exception could not be added" >&2; return 0; }
    if [[ "$python" != "$realhome/"?* ]]; then
        echo "firewall: not changed, $python is outside $realhome; allow it in System" \
            "Settings > Network > Firewall if other devices should reach voiced"
        return 0
    fi
    if [ -f "$python" ] && [ ! -L "$python" ] && [ "$(stat -f %u -- "$python")" = "$uid" ] \
        && "$fw" --add "$python" >/dev/null && "$fw" --unblockapp "$python" >/dev/null; then
        echo "firewall: $python may accept incoming connections"
    else
        echo "warning: the firewall exception could not be added" >&2
    fi
}

# stt
launchctl bootout system/org.example.voiced.stt 2>/dev/null || true
for _ in $(seq 1 30); do launchctl print system/org.example.voiced.stt >/dev/null 2>&1 || break; sleep 1; done
cp /Users/someone/.config/voiced/launchd/org.example.voiced.stt.plist /Library/LaunchDaemons/org.example.voiced.stt.plist
chown root:wheel /Library/LaunchDaemons/org.example.voiced.stt.plist
chmod 644 /Library/LaunchDaemons/org.example.voiced.stt.plist
launchctl bootstrap system /Library/LaunchDaemons/org.example.voiced.stt.plist

# tts
launchctl bootout system/org.example.voiced.tts 2>/dev/null || true
for _ in $(seq 1 30); do launchctl print system/org.example.voiced.tts >/dev/null 2>&1 || break; sleep 1; done
cp /Users/someone/.config/voiced/launchd/org.example.voiced.tts.plist /Library/LaunchDaemons/org.example.voiced.tts.plist
chown root:wheel /Library/LaunchDaemons/org.example.voiced.tts.plist
chmod 644 /Library/LaunchDaemons/org.example.voiced.tts.plist
launchctl bootstrap system /Library/LaunchDaemons/org.example.voiced.tts.plist

# watchdog
launchctl bootout system/org.example.voiced.watchdog 2>/dev/null || true
for _ in $(seq 1 30); do launchctl print system/org.example.voiced.watchdog >/dev/null 2>&1 || break; sleep 1; done
cp /Users/someone/.config/voiced/launchd/org.example.voiced.watchdog.plist /Library/LaunchDaemons/org.example.voiced.watchdog.plist
chown root:wheel /Library/LaunchDaemons/org.example.voiced.watchdog.plist
chmod 644 /Library/LaunchDaemons/org.example.voiced.watchdog.plist
launchctl bootstrap system /Library/LaunchDaemons/org.example.voiced.watchdog.plist

firewall
echo 'voiced daemons installed. Check with:'
echo '  /Users/someone/.voiced/bin/voiced status'
